class Solution {public:int minimumSubarrayLength(vector<int>& nums,int k){
 int cnt[31]={},v=0,l=0,ans=INT_MAX;auto update=[&](int x,int delta){for(int b=0;b<31;b++)if(x&(1<<b)){cnt[b]+=delta;if(cnt[b])v|=1<<b;else v&=~(1<<b);}};
 for(int r=0;r<(int)nums.size();r++){update(nums[r],1);while(l<=r&&v>=k){ans=min(ans,r-l+1);update(nums[l++],-1);}}return ans==INT_MAX?-1:ans;
}};
